 *   T11 multi-runtime isolation (different stdlib per runtime)
 *   T12 bitmask introspection
 *   T13 frost_runtime_create() still has full stdlib (Stage 1 compat)
 */
#include "frostcore.h"
#include "frostcore_subsystems.h"

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* -----------------------------------------------------------------------
 * Helpers
 * ----------------------------------------------------------------------- */
static int test_pass = 0;
static int test_fail = 0;

#define PASS(label) do { \
    printf("  PASS %s\n", label); \
    test_pass++; \
} while(0)

#define FAIL(label, detail) do { \
    fprintf(stderr, "  FAIL %s: %s\n", label, detail); \
    test_fail++; \
} while(0)

static void eval_expect_ok(frost_runtime *rt, const char *src, const char *label)
{
    char *err = NULL;
    int rc = frost_eval(rt, src, &err);
    if (rc == 0) {
        PASS(label);
    } else {
        char buf[512];
        snprintf(buf, sizeof(buf), "eval(%s) => error: %s", src, err ? err : "(null)");
        FAIL(label, buf);
    }
    free(err);
}

static void eval_expect_fail(frost_runtime *rt, const char *src,
                              const char *substr, const char *label)
{
    char *err = NULL;
    int rc = frost_eval(rt, src, &err);
    if (rc != 0) {
        /* If substr given, verify it appears in the error */
        if (!substr || (err && strstr(err, substr))) {
            PASS(label);
        } else {
            char buf[512];
            snprintf(buf, sizeof(buf),
                     "expected error containing '%s', got: %s", substr, err ? err : "(null)");
            FAIL(label, buf);
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "eval(%s) expected error but returned 0", src);
        FAIL(label, buf);
    }
    free(err);
}

static void reg_expect_ok(int rc, char *err, const char *label)
{
    if (rc == 0) {
        PASS(label);
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "registration failed: %s", err ? err : "(null)");
        FAIL(label, buf);
    }
    free(err);
}

static void reg_expect_fail(int rc, char *err, const char *substr, const char *label)
{
    if (rc != 0) {
        if (!substr || (err && strstr(err, substr))) {
            PASS(label);
        } else {
            char buf[512];
            snprintf(buf, sizeof(buf),
                     "expected error containing '%s', got: %s", substr, err ? err : "(null)");
            FAIL(label, buf);
        }
    } else {
        FAIL(label, "expected registration failure but got 0");
    }
    free(err);
}

/* -----------------------------------------------------------------------
 * T1 — Bare runtime: VM functional, zero globals
 * ----------------------------------------------------------------------- */
static void test_t1_bare_vm(void)
{
    printf("\n[T1] Bare runtime — VM runs, zero stdlib globals\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt && "frost_runtime_create_bare returned NULL");

    /* VM executes — literals, operators, typeof all work */
    eval_expect_ok(rt,   "1 + 2",          "T1/arithmetic");
    eval_expect_ok(rt,   "typeof undefined","T1/typeof-undefined");
    eval_expect_ok(rt,   "true && false",   "T1/boolean");
    eval_expect_ok(rt,   "null",            "T1/null-literal");

    /* throw / try-catch work even without stdlib */
    eval_expect_ok(rt,
        "(function(){ try { throw 42; } catch(e) { return e === 42; } })()",
        "T1/throw-catch");

    /* No global constructors — Object is not defined */
    eval_expect_fail(rt, "Object.keys({})", NULL, "T1/Object-absent");
    eval_expect_fail(rt, "Array.isArray([])", NULL, "T1/Array-absent");
    eval_expect_fail(rt, "JSON.stringify(1)", NULL, "T1/JSON-absent");
    eval_expect_fail(rt, "Math.sqrt(4)",     NULL, "T1/Math-absent");
    eval_expect_fail(rt, "Promise.resolve(1)", NULL, "T1/Promise-absent");
    eval_expect_fail(rt, "Date.now()",       NULL, "T1/Date-absent");
    eval_expect_fail(rt, "console.log('x')", NULL, "T1/console-absent");

    /* bitmask is 0 */
    if (frost_subsystems_registered(rt) == 0)
        PASS("T1/bitmask-zero");
    else
        FAIL("T1/bitmask-zero", "expected 0");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T2 — Dependency ordering enforcement
 * ----------------------------------------------------------------------- */
static void test_t2_deps(void)
{
    printf("\n[T2] Dependency ordering enforcement\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    char *err;

    /* All non-core subsystems should fail without std_core */
    err = NULL;
    reg_expect_fail(frost_register_std_collections(rt, &err), err, "std_core",
                    "T2/collections-needs-core");

    err = NULL;
    reg_expect_fail(frost_register_std_async(rt, &err), err, "std_core",
                    "T2/async-needs-core");

    err = NULL;
    reg_expect_fail(frost_register_std_time(rt, &err), err, "std_core",
                    "T2/time-needs-core");

    err = NULL;
    reg_expect_fail(frost_register_std_io(rt, &err), err, "std_core",
                    "T2/io-needs-core");

    /* Now install core — subsequent calls succeed */
    err = NULL;
    reg_expect_ok(frost_register_std_core(rt, &err), err, "T2/core-installs");

    err = NULL;
    reg_expect_ok(frost_register_std_collections(rt, &err), err,
                  "T2/collections-after-core");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T3 — Idempotency
 * ----------------------------------------------------------------------- */
static void test_t3_idempotent(void)
{
    printf("\n[T3] Idempotency — double-register is safe\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    char *err;

    /* Register core twice */
    err = NULL; reg_expect_ok(frost_register_std_core(rt, &err), err, "T3/core-first");
    err = NULL; reg_expect_ok(frost_register_std_core(rt, &err), err, "T3/core-second");

    err = NULL; reg_expect_ok(frost_register_std_async(rt, &err), err, "T3/async-first");
    err = NULL; reg_expect_ok(frost_register_std_async(rt, &err), err, "T3/async-second");

    err = NULL; reg_expect_ok(frost_register_std_time(rt, &err), err, "T3/time-first");
    err = NULL; reg_expect_ok(frost_register_std_time(rt, &err), err, "T3/time-second");

    err = NULL; reg_expect_ok(frost_register_std_io(rt, &err), err, "T3/io-first");
    err = NULL; reg_expect_ok(frost_register_std_io(rt, &err), err, "T3/io-second");

    /* JS state should still be consistent after double-registration */
    eval_expect_ok(rt, "JSON.stringify([1,2,3])", "T3/json-still-works");
    eval_expect_ok(rt, "Promise.resolve(42)", "T3/promise-still-works");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T4 — std_core correctness
 * ----------------------------------------------------------------------- */
static void test_t4_core(void)
{
    printf("\n[T4] std_core — Object, Array, String, Math, eval, RegExp, JSON, Proxy, Map\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    char *err = NULL;
    reg_expect_ok(frost_register_std_core(rt, &err), err, "T4/core-register");

    /* Object */
    eval_expect_ok(rt, "Object.keys({a:1,b:2}).length === 2", "T4/Object.keys");
    eval_expect_ok(rt, "Object.assign({}, {x:1}).x === 1",    "T4/Object.assign");

    /* Array */
    eval_expect_ok(rt, "[1,2,3].map(x=>x*2).join(',') === '2,4,6'", "T4/Array.map");
    eval_expect_ok(rt, "Array.isArray([])",                          "T4/Array.isArray");
    eval_expect_ok(rt, "[1,2,3].filter(x=>x>1).length === 2",       "T4/Array.filter");

    /* String */
    eval_expect_ok(rt, "'hello'.toUpperCase() === 'HELLO'", "T4/String.toUpperCase");
    eval_expect_ok(rt, "'  x  '.trim() === 'x'",            "T4/String.trim");

    /* Math */
    eval_expect_ok(rt, "Math.sqrt(9) === 3",   "T4/Math.sqrt");
    eval_expect_ok(rt, "Math.max(1,2,3) === 3","T4/Math.max");
    eval_expect_ok(rt, "Math.abs(-5) === 5",   "T4/Math.abs");
    eval_expect_ok(rt, "Math.floor(1.9) === 1","T4/Math.floor");

    /* Number */
    eval_expect_ok(rt, "Number.isFinite(42)", "T4/Number.isFinite");
    eval_expect_ok(rt, "Number.isNaN(NaN)",   "T4/Number.isNaN");
    eval_expect_ok(rt, "(1.5).toFixed(1) === '1.5'", "T4/toFixed");

    /* eval() */
    eval_expect_ok(rt, "eval('1+1') === 2", "T4/eval");

    /* RegExp */
    eval_expect_ok(rt, "/^hello/.test('hello world')", "T4/regexp-literal");
    eval_expect_ok(rt, "new RegExp('\\\\d+').test('42')", "T4/regexp-ctor");
    eval_expect_ok(rt, "'abc123'.match(/\\d+/)[0] === '123'", "T4/string-match");

    /* JSON */
    eval_expect_ok(rt, "JSON.stringify({x:1}) === '{\"x\":1}'", "T4/JSON.stringify");
    eval_expect_ok(rt, "JSON.parse('{\"x\":1}').x === 1",       "T4/JSON.parse");

    /* Proxy */
    eval_expect_ok(rt,
        "(function(){"
        "  var p = new Proxy({}, { get: function(_,k){ return k==='foo'?42:undefined; } });"
        "  return p.foo === 42;"
        "})()",
        "T4/Proxy");

    /* Map / Set */
    eval_expect_ok(rt, "(function(){ var m=new Map(); m.set('k',99); return m.get('k')===99; })()",
                   "T4/Map");
    eval_expect_ok(rt, "(function(){ var s=new Set([1,2,2,3]); return s.size===3; })()",
                   "T4/Set");

    /* Error hierarchy */
    eval_expect_ok(rt,
        "(function(){ try { null.x; } catch(e){ return e instanceof TypeError; } })()",
        "T4/TypeError");
    eval_expect_ok(rt,
        "(function(){ try { undeclared; } catch(e){ return e instanceof ReferenceError; } })()",
        "T4/ReferenceError");

    /* Symbol */
    eval_expect_ok(rt, "typeof Symbol('x') === 'symbol'", "T4/Symbol");
    eval_expect_ok(rt,
        "(function(){ var s=Symbol('tag'); var o={}; o[s]=1; return o[s]===1; })()",
        "T4/Symbol-as-key");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
