    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T6 — std_async
 * ----------------------------------------------------------------------- */
static void test_t6_async(void)
{
    printf("\n[T6] std_async — Promise, atob/btoa, DOMException\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    char *err;
    err = NULL; reg_expect_ok(frost_register_std_core(rt, &err),  err, "T6/core");
    err = NULL; reg_expect_ok(frost_register_std_async(rt, &err), err, "T6/async");

    /* Promise */
    eval_expect_ok(rt, "typeof Promise === 'function'", "T6/Promise-exists");
    eval_expect_ok(rt,
        "(function(){"
        "  var resolved = false;"
        "  var p = Promise.resolve(42);"
        "  p.then(function(v){ resolved = (v===42); });"
        "  return typeof p.then === 'function';"
        "})()",
        "T6/Promise.resolve");

    eval_expect_ok(rt,
        "(function(){"
        "  var p = Promise.reject(new Error('x'));"
        "  p.catch(function(){}); /* suppress unhandled */ "
        "  return p instanceof Promise;"
        "})()",
        "T6/Promise.reject");

    eval_expect_ok(rt,
        "(function(){"
        "  var results = [];"
        "  return Promise.all([Promise.resolve(1), Promise.resolve(2)]) instanceof Promise;"
        "})()",
        "T6/Promise.all");

    /* atob / btoa */
    eval_expect_ok(rt, "btoa('hello') === 'aGVsbG8='",       "T6/btoa");
    eval_expect_ok(rt, "atob('aGVsbG8=') === 'hello'",       "T6/atob");
    eval_expect_ok(rt, "atob(btoa('FrostCore')) === 'FrostCore'", "T6/roundtrip");

    /* DOMException */
    eval_expect_ok(rt, "typeof DOMException === 'function'", "T6/DOMException-exists");

    /* Promise absent without registration */
    {
        frost_runtime *bare = frost_runtime_create_bare(NULL);
        assert(bare);
        err = NULL; frost_register_std_core(bare, &err); free(err);
        eval_expect_fail(bare, "Promise.resolve(1)", NULL, "T6/Promise-absent-without-async");
        frost_runtime_destroy(bare);
    }

    frost_runtime_destroy(rt);
}

