23	/* -----------------------------------------------------------------------
24	 * Counting allocator
25	 * ----------------------------------------------------------------------- */
26	typedef struct {
27	    long allocs;
28	    long frees;
29	} alloc_stats;
30	
31	static void *counting_alloc(size_t size, void *ud)
32	{
33	    alloc_stats *s = (alloc_stats *)ud;
34	    s->allocs++;
35	    return malloc(size);
36	}
37	
38	static void counting_free(void *ptr, void *ud)
39	{
40	    alloc_stats *s = (alloc_stats *)ud;
41	    if (ptr) s->frees++;
42	    free(ptr);
43	}
44	
45	static void *counting_realloc(void *ptr, size_t size, void *ud)
46	{
47	    /* realloc from NULL counts as an alloc; to NULL counts as a free */
48	    alloc_stats *s = (alloc_stats *)ud;
49	    if (!ptr) s->allocs++;
50	    if (size == 0 && ptr) s->frees++;
51	    return realloc(ptr, size);
52	}
53	
54	static void *counting_calloc(size_t count, size_t size, void *ud)
55	{
56	    alloc_stats *s = (alloc_stats *)ud;
57	    s->allocs++;
58	    return calloc(count, size);
59	}
