16	 *
17	 * registered_subsystems tracks which frost_register_std_*() calls have
18	 * completed so we can enforce dependency ordering and provide idempotency.
19	 * ----------------------------------------------------------------------- */
20	struct frost_runtime {
21	    JSRuntime    *js_rt;
22	    JSContext    *js_ctx;
23	    frost_alloc   alloc;               /* copy of caller's vtable */
24	    unsigned int  registered_subsystems; /* bitmask of FROST_STD_* flags */
25	};
