27	/* -----------------------------------------------------------------------
28	 * Default system allocator -- used when caller passes alloc == NULL
29	 * ----------------------------------------------------------------------- */
30	static void *sys_calloc(size_t count, size_t size, void *ud)
31	{
32	    (void)ud;
33	    return calloc(count, size);
34	}
35	
36	static void *sys_alloc(size_t size, void *ud)
37	{
38	    (void)ud;
39	    return malloc(size);
40	}
41	
42	static void sys_free(void *ptr, void *ud)
43	{
44	    (void)ud;
45	    free(ptr);
46	}
