63	/* -----------------------------------------------------------------------
64	 * JSMallocFunctions adapter thunks
65	 *
66	 * quickjs-ng passes opaque as the first arg. We store frost_runtime* there
67	 * so the thunks can reach frost_runtime.alloc.userdata.
68	 * ----------------------------------------------------------------------- */
69	static void *thunk_calloc(void *opaque, size_t count, size_t size)
70	{
71	    frost_runtime *fr = (frost_runtime *)opaque;
72	    if (fr->alloc.calloc)
73	        return fr->alloc.calloc(count, size, fr->alloc.userdata);
74	    void *p = fr->alloc.alloc(count * size, fr->alloc.userdata);
75	    if (p) memset(p, 0, count * size);
76	    return p;
77	}
78	
79	static void *thunk_malloc(void *opaque, size_t size)
80	{
81	    frost_runtime *fr = (frost_runtime *)opaque;
82	    return fr->alloc.alloc(size, fr->alloc.userdata);
83	}
84	
85	static void thunk_free(void *opaque, void *ptr)
86	{
87	    frost_runtime *fr = (frost_runtime *)opaque;
88	    fr->alloc.free(ptr, fr->alloc.userdata);
89	}
90	
91	static void *thunk_realloc(void *opaque, void *ptr, size_t size)
92	{
93	    frost_runtime *fr = (frost_runtime *)opaque;
94	    return fr->alloc.realloc(ptr, size, fr->alloc.userdata);
95	}
