104	/* -----------------------------------------------------------------------
105	 * Internal: allocate and wire up a frost_runtime with a JS runtime.
106	 * The JS context is left NULL -- callers set it after.
107	 * ----------------------------------------------------------------------- */
108	static frost_runtime *alloc_runtime(const frost_alloc *alloc)
109	{
110	    const frost_alloc *a = alloc ? alloc : &k_sys_alloc;
111	
112	    if (!a->alloc || !a->free || !a->realloc)
113	        return NULL;
114	
115	    frost_runtime *fr = (frost_runtime *)a->alloc(sizeof(frost_runtime), a->userdata);
116	    if (!fr) return NULL;
117	
118	    fr->alloc                = *a;
119	    fr->js_ctx               = NULL;
120	    fr->registered_subsystems = 0;
121	
122	    JSMallocFunctions mf = {
123	        thunk_calloc,
124	        thunk_malloc,
125	        thunk_free,
126	        thunk_realloc,
127	        a->malloc_usable_size ? a->malloc_usable_size : thunk_usable_size,
128	    };
129	
130	    fr->js_rt = JS_NewRuntime2(&mf, (void *)fr);
131	    if (!fr->js_rt) {
132	        a->free(fr, a->userdata);
133	        return NULL;
134	    }
135	
136	    return fr;
137	}
