142	frost_runtime *frost_runtime_create(const frost_alloc *alloc)
143	{
144	    frost_runtime *fr = alloc_runtime(alloc);
145	    if (!fr) return NULL;
146	
147	    /* JS_NewContext installs the complete quickjs-ng stdlib */
148	    fr->js_ctx = JS_NewContext(fr->js_rt);
149	    if (!fr->js_ctx) {
150	        JS_FreeRuntime(fr->js_rt);
151	        fr->alloc.free(fr, fr->alloc.userdata);
152	        return NULL;
153	    }
154	
155	    /* Mark every subsystem as registered -- it was done by JS_NewContext */
156	    fr->registered_subsystems =
157	        FROST_STD_CORE | FROST_STD_COLLECTIONS |
158	        FROST_STD_ASYNC | FROST_STD_TIME;
